(function(){'use strict';
const L=LedgerUI,$=id=>document.getElementById(id),fmt=n=>Number(n).toLocaleString('ru-RU',{maximumFractionDigits:2}),dialog=document.createElement('dialog'),undo=new Map();let pending=null;
dialog.id='history-delete-dialog';dialog.className='history-delete-dialog';dialog.setAttribute('aria-labelledby','history-delete-title');document.body.append(dialog);
function context(uid){const s=L.store.snapshot(),b=s.batches.find(b=>b.uid===uid);return JSON.stringify([window.Workspace?.ticket(),L.history.state.server,b,s.deals.filter(d=>d.batch===uid)]);}
function close(){const focus=pending?.focus;pending=null;dialog.close();if(focus?.isConnected&&focus.checkVisibility())focus.focus({preventScroll:true});}
function showUndo(){const server=L.history.state.server,token=undo.get(server);let button=$('history-undo-delete');if(!button){button=document.createElement('button');button.id='history-undo-delete';button.className='button';button.type='button';button.textContent='Отменить удаление';$('history-status').after(button);button.onclick=()=>{try{const server=L.history.state.server,token=undo.get(server);if(!token)return;L.store.restoreBatch(token);undo.delete(server);document.dispatchEvent(new Event('ledgerchange'));$('history-status').textContent='Запись и связанные сделки восстановлены.';showUndo();}catch(error){$('history-status').textContent=error.message;}};}button.hidden=!token;}
function open(uid){const b=L.store?.snapshot().batches.find(b=>b.uid===uid&&b.server===L.history.state.server);if(!b||dialog.open)return;const deals=L.store.snapshot().deals.filter(d=>d.batch===uid);pending={uid,server:b.server,context:context(uid),focus:document.activeElement};dialog.innerHTML='<div class="section-heading"><h2 id="history-delete-title">Удалить запись о партии?</h2><button id="history-delete-close" type="button" class="button">Закрыть</button></div><p id="history-delete-item"></p><p id="history-delete-amount"></p><p id="history-delete-deals"></p><label id="history-delete-linked-wrap" class="history-delete-linked"><input id="history-delete-linked" type="checkbox"> Удалить также связанные сделки этой партии</label><p id="history-delete-error" class="negative" role="status"></p><div class="history-delete-actions"><button id="history-delete-confirm" type="button" class="button">Удалить запись</button><button id="history-delete-cancel" type="button" class="button primary">Оставить запись</button></div><p class="hint">Можно отменить последнее удаление до перезапуска приложения.</p>';
 $('history-delete-item').textContent=b.name+' · '+new Date(b.date).toLocaleString('ru-RU')+' · '+b.characterName;$('history-delete-amount').textContent='Изготовлено '+fmt(b.quantity)+' шт. · остаток '+fmt(b.remaining)+' шт. · себестоимость '+fmt(b.totalCost)+' серебра.';$('history-delete-deals').textContent=deals.length?'Связанных сделок: '+deals.length+'. Их удаление изменит сумму записанной прибыли.':'Связанных сделок нет.';$('history-delete-linked-wrap').hidden=!deals.length;$('history-delete-confirm').disabled=deals.length>0;$('history-delete-linked').onchange=()=>{$('history-delete-confirm').disabled=deals.length>0&&!$('history-delete-linked').checked;};
 $('history-delete-close').onclick=close;$('history-delete-cancel').onclick=close;$('history-delete-confirm').onclick=()=>{if(!pending)return;if(pending.context!==context(pending.uid)){close();$('history-status').textContent='Запись изменилась. Откройте удаление заново.';return;}try{const token=L.store.deleteBatch(pending.uid,{withDeals:$('history-delete-linked').checked}),server=pending.server;undo.set(server,token);close();document.dispatchEvent(new Event('ledgerchange'));$('history-status').textContent='Запись о партии удалена.';showUndo();$('history-undo-delete').focus({preventScroll:true});}catch(error){$('history-delete-error').textContent=error.message;}};dialog.showModal();$('history-delete-cancel').focus();}
dialog.addEventListener('cancel',e=>{e.preventDefault();close();});document.addEventListener('workspacechange',()=>{if(pending&&pending.context!==context(pending.uid))close();showUndo();});document.addEventListener('ledgerchange',showUndo);showUndo();window.HistoryDeleteUI={open};
})();
